CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), name varchar(80) UNIQUE NOT NULL, type varchar(30) NOT NULL, status varchar(20) NOT NULL DEFAULT 'healthy', baseline_latency double precision NOT NULL, current_latency double precision NOT NULL, error_rate double precision NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dependencies (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), source_service varchar(80) NOT NULL, target_service varchar(80) NOT NULL, direction varchar(20) NOT NULL DEFAULT 'CALLS', UNIQUE(source_service,target_service));
CREATE TABLE fault_injections (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), type varchar(40) NOT NULL, target varchar(80) NOT NULL, severity varchar(20) NOT NULL, duration_seconds integer NOT NULL, parameters jsonb NOT NULL DEFAULT '{}'::jsonb, status varchar(20) NOT NULL DEFAULT 'ACTIVE', started_at timestamptz NOT NULL DEFAULT now(), stopped_at timestamptz);
CREATE TABLE telemetry_snapshots (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), service_name varchar(80) NOT NULL, captured_at timestamptz NOT NULL DEFAULT now(), p50_latency double precision NOT NULL, p95_latency double precision NOT NULL, p99_latency double precision NOT NULL, error_rate double precision NOT NULL, request_rate double precision NOT NULL, db_latency double precision, pool_utilization double precision, anomaly_score double precision NOT NULL DEFAULT 0, attributes jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX telemetry_service_time ON telemetry_snapshots(service_name,captured_at DESC);
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), incident_key varchar(30) UNIQUE NOT NULL, title varchar(160) NOT NULL, severity varchar(20) NOT NULL, status varchar(40) NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, summary text NOT NULL, affected_services jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE incident_events (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), incident_id uuid REFERENCES incidents(id) ON DELETE CASCADE, occurred_at timestamptz NOT NULL DEFAULT now(), event_type varchar(40) NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE root_cause_analyses (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), incident_id uuid REFERENCES incidents(id) ON DELETE CASCADE, completed_at timestamptz NOT NULL DEFAULT now(), methodology varchar(120) NOT NULL, root_cause varchar(80), confidence double precision NOT NULL, evidence jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE root_cause_candidates (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), analysis_id uuid REFERENCES root_cause_analyses(id) ON DELETE CASCADE, service_name varchar(80) NOT NULL, score double precision NOT NULL, signals jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE predictions (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), service_name varchar(80) NOT NULL, probability double precision NOT NULL, risk_level varchar(20) NOT NULL, horizon_seconds integer NOT NULL, factors jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE prediction_factors (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), prediction_id uuid REFERENCES predictions(id) ON DELETE CASCADE, name varchar(100), contribution double precision, detail text);
CREATE TABLE simulations (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), target varchar(80) NOT NULL, intervention jsonb NOT NULL, status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE simulation_results (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), simulation_id uuid REFERENCES simulations(id) ON DELETE CASCADE, service_name varchar(80), baseline double precision, counterfactual double precision, classification varchar(20) NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE log_events (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), service_name varchar(80), level varchar(10), message text, trace_id varchar(64), occurred_at timestamptz NOT NULL DEFAULT now(), attributes jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE trace_summaries (id uuid PRIMARY KEY DEFAULT uuid_generate_v4(), trace_id varchar(64), service_name varchar(80), operation varchar(160), duration_ms double precision, status varchar(20), started_at timestamptz NOT NULL DEFAULT now(), attributes jsonb NOT NULL DEFAULT '{}'::jsonb);
